请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-054

=== 用户原始指令 (query.txt) ===
{"scenario": "03-anti-addiction", "scenario_name": "防沉迷", "query": "给我做个防沉迷卡片，顶部用主题色铺满当背景，放个大号的“今日时长已超限45%”告警提示，底部横排几个游戏应用的复选框任务，让我选今天禁用哪些。用那种带有紧迫感的红橙渐变色，最好用带感叹号的警告图标，选好之后点确认能直接跳到系统设置里的应用时长管理页面去执行。数据你就随便填点静态示例就行。", "axes": {"size": "2x2", "component": "Checkbox", "binding": "formatString", "click": "deeplink_settings", "data": "static", "surface": "colored-root", "composition": "hero-top", "status": "alert", "gradient": "action-fill", "asset": "icon", "template": "row"}, "source": "10k"}

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个防沉迷卡片，顶部用主题色铺满当背景，放个大号的“今日时长已超限45%”告警提示，底部横排几个游戏应用的复选框任务，让我选今天禁用哪些。用那种带有紧迫感的红橙渐变色，最好用带感叹号的警告图标，选好之后点确认能直接跳到系统设置里的应用时长管理页面去执行。数据你就随便填点静态示例就行。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModel": {
    "value": {
      "antiAddiction": {
        "status": "今日时长已超限45%",
        "actionText": "确认",
        "warningIcon": "resources/base/media/icon_timing.png",
        "apps": [
          {
            "name": "星战",
            "disabledToday": true
          },
          {
            "name": "竞速",
            "disabledToday": false
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "warning_timer_icon",
      "src": "resources/base/media/icon_timing.png",
      "use": "anti-addiction warning icon",
      "description": "防沉迷/应用用量计时图标，适合作为今日使用时长超限的告警视觉锚点。",
      "bindTo": "/antiAddiction/warningIcon",
      "static": true
    }
  ]
}

